package com.gearvrf.stl;

import android.os.Handler;
import android.os.HandlerThread;
import android.os.Message;
import android.view.InputDevice;
import android.view.KeyEvent;
import android.view.MotionEvent;

/**
 * Use this class to translate MotionEvents and KeyEvents generated by the
 * controller to values that can be used to create InputEvents for the GVRf
 * GVRInputManager.
 *
 */
public class STLController {
    private static final String TAG = STLController.class.getSimpleName();
    private final EventHandlerThread thread;

    public interface ControllerListener {
        /**
         * This method is called whenever an Event is passed to the
         * {@link STLController} class.
         * 
         * Note that this call happens on the EventHandlerThread.
         * 
         * @param x
         *            returns the joystick displacement along the x axis
         * @param y
         *            returns the joystick displacement along the y axis
         * @param z
         *            returns the joystick displacement along the z axis
         * @param active
         *            returns <code>true</code> on button press and
         *            <code>false</code> on release
         */
        public void onEvent(float x, float y, float z, boolean active);
    }

    public STLController(ControllerListener listener) {
        thread = new EventHandlerThread("EventHandlerThread", listener);
        thread.start();
        thread.prepareHandler();
    }

    public void close() {
        thread.quit();
    }

    public boolean dispatchKeyEvent(KeyEvent event) {
        return thread.submitKeyEvent(event);
    }

    public boolean dispatchMotionEvent(MotionEvent event) {
        MotionEvent clone = MotionEvent.obtain(event);
        return thread.submitMotionEvent(clone);
    }

    private static class EventHandlerThread extends HandlerThread {
        private static final int MOTION_EVENT = 1;
        private static final int KEY_EVENT = 2;
        private Handler handler;
        private final ControllerListener listener;
        private boolean isActive = false;
        private float x, y, ry;
        private InputDevice mInputDevice;

        EventHandlerThread(String name, ControllerListener listener) {
            super(name);
            this.listener = listener;
        }

        void prepareHandler() {
            handler = new Handler(getLooper()) {
                @Override
                public void handleMessage(Message msg) {
                    super.handleMessage(msg);
                    switch (msg.what) {
                    case MOTION_EVENT:
                        MotionEvent motionEvent = (MotionEvent) msg.obj;
                        dispatchMotionEvent(motionEvent);
                        motionEvent.recycle();
                        break;
                    case KEY_EVENT:
                        KeyEvent keyEvent = (KeyEvent) msg.obj;
                        dispatchKeyEvent(keyEvent);
                        break;
                    default:
                        break;
                    }
                }
            };
        }

        private void dispatchKeyEvent(KeyEvent event) {
            int keyCode = event.getKeyCode();
            if (keyCode == KeyEvent.KEYCODE_BUTTON_A
                    || keyCode == KeyEvent.KEYCODE_BUTTON_B
                    || keyCode == KeyEvent.KEYCODE_BUTTON_X
                    || keyCode == KeyEvent.KEYCODE_BUTTON_Y
                    || keyCode == KeyEvent.KEYCODE_BUTTON_L1
                    || keyCode == KeyEvent.KEYCODE_BUTTON_R1) {
                int action = event.getAction();
                if (action == KeyEvent.ACTION_DOWN && isActive == false) {
                    isActive = true;
                    listener.onEvent(x, y, ry, isActive);
                } else if (action == KeyEvent.ACTION_UP && isActive == true) {
                    isActive = false;
                    listener.onEvent(x, y, ry, isActive);
                }
            }
        }

        boolean submitMotionEvent(MotionEvent event) {
            Message message = Message.obtain(null, MOTION_EVENT, 0, 0, event);
            return handler.sendMessage(message);
        }

        boolean submitKeyEvent(KeyEvent event) {
            Message message = Message.obtain(null, KEY_EVENT, 0, 0, event);
            return handler.sendMessage(message);
        }

        // The following methods are taken from the controller sample on the
        // Android Developer web site:
        // https://developer.android.com/training/game-controllers/controller-input.html
        private void dispatchMotionEvent(MotionEvent event) {
            int eventSource = event.getSource();
            if ((((eventSource
                    & InputDevice.SOURCE_GAMEPAD) == InputDevice.SOURCE_GAMEPAD)
                    || ((eventSource
                            & InputDevice.SOURCE_JOYSTICK) == InputDevice.SOURCE_JOYSTICK))
                    && event.getAction() == MotionEvent.ACTION_MOVE) {
                int id = event.getDeviceId();
                if (id != -1) {

                    final int historySize = event.getHistorySize();
                    for (int i = 0; i < historySize; i++) {
                        processJoystickInput(event, i);
                    }
                    processJoystickInput(event, -1);
                }
            }
        }

        private void processJoystickInput(MotionEvent event, int historyPos) {
            if (null == mInputDevice) {
                mInputDevice = event.getDevice();
            }

            float x = getCenteredAxis(event, mInputDevice, MotionEvent.AXIS_X,
                    historyPos);
            if (x == 0) {
                x = getCenteredAxis(event, mInputDevice, MotionEvent.AXIS_HAT_X,
                        historyPos);
            }
            if (x == 0) {
                x = getCenteredAxis(event, mInputDevice, MotionEvent.AXIS_Z,
                        historyPos);
            }

            float y = getCenteredAxis(event, mInputDevice, MotionEvent.AXIS_Y,
                    historyPos);
            if (y == 0) {
                y = getCenteredAxis(event, mInputDevice, MotionEvent.AXIS_HAT_Y,
                        historyPos);
            }
            if (y == 0) {
                y = getCenteredAxis(event, mInputDevice, MotionEvent.AXIS_RZ,
                        historyPos);
            }

            float ry = getCenteredAxis(event, mInputDevice, MotionEvent.AXIS_RY,
                    historyPos);
            this.x = x;
            this.y = -y;
            this.ry = ry;
            listener.onEvent(this.x, this.y, this.ry, isActive);
        }

        private static float getCenteredAxis(MotionEvent event,
                InputDevice device, int axis, int historyPos) {
            final InputDevice.MotionRange range = device.getMotionRange(axis,
                    event.getSource());

            if (range != null) {
                final float flat = range.getFlat();
                final float value = historyPos < 0 ? event.getAxisValue(axis)
                        : event.getHistoricalAxisValue(axis, historyPos);

                if (Math.abs(value) > flat) {
                    return value;
                }
            }
            return 0;
        }
    }
}
